-- AI: exact consumed-source and management catalogs only; no application/Auth rows.
begin read only;
set local statement_timeout='5s';
select jsonb_build_object(
 'capturedAt',clock_timestamp(),'projectId','xlrubcwjqktzzunrvuns',
 'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'udt',udt_name,'nullable',is_nullable) order by table_name,ordinal_position) from information_schema.columns where table_schema='rakeezx' and table_name in ('years','terms','sections','students','enrollments','teachings','items','scores','score_subitems','score_subitem_completions','sessions','attendance','logs')),
 'tables',(select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='rakeezx' and c.relname in ('years','terms','sections','students','enrollments','teachings','items','scores','score_subitems','score_subitem_completions','sessions','attendance','logs') and c.relkind in ('r','p')),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated,'deferrable',k.condeferrable) order by c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='rakeezx' and c.relname in ('years','terms','sections','students','enrollments','teachings','items','scores','score_subitems','score_subitem_completions','sessions','attendance','logs')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'functionOwner',pg_get_userbyid(p.proowner),'functionMd5',md5(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n'))) order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where n.nspname='rakeezx' and c.relname in ('years','terms','sections','students','enrollments','teachings','items','scores','score_subitems','score_subitem_completions','sessions','attendance','logs') and not t.tgisinternal),
 'authTables',(select jsonb_agg(jsonb_build_object('table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'policyCount',(select count(*) from pg_policy q where q.polrelid=c.oid)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='auth' and c.relname in ('users','sessions')),
 'authStatusColumns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'udt',udt_name,'nullable',is_nullable) order by table_name,column_name) from information_schema.columns where table_schema='auth' and ((table_name='users' and column_name in ('id','banned_until')) or (table_name='sessions' and column_name in ('id','user_id','not_after')))),
 'management',jsonb_build_object('currentUser',current_user,'sessionUser',session_user,'superuser',(select rolsuper from pg_roles where rolname=current_user),'bypassRls',(select rolbypassrls from pg_roles where rolname=current_user),'authReferences',has_column_privilege(current_user,'auth.users','id','REFERENCES'),'authSchemaUsage',has_schema_privilege(current_user,'auth','USAGE'),'authOwnerMember',pg_has_role(current_user,'supabase_auth_admin','MEMBER'),'authSchemaCreate',has_schema_privilege(current_user,'auth','CREATE')),
 'statusLockPrivileges',(select jsonb_agg(jsonb_build_object('table',x.tbl,'column',x.col,'select',has_column_privilege(current_user,'auth.'||x.tbl,x.col,'SELECT'),'update',has_column_privilege(current_user,'auth.'||x.tbl,x.col,'UPDATE'))) from (values ('users','id'),('users','banned_until'),('sessions','id'),('sessions','user_id'),('sessions','not_after')) x(tbl,col)),
 'n88',jsonb_build_object('schemaExists',exists(select 1 from pg_namespace where nspname='n88_private'),'backendExists',exists(select 1 from pg_roles where rolname='n88_backend'),'guardExists',exists(select 1 from pg_roles where rolname='n88_guard'))
) as catalog;
rollback;
